		}

		if len(matches) == 0 {
			if s.kind == "left" {
				nr := r.Copy()
				s.addRightColumns(nr, nil, schema)
				out = append(out, nr)
			}
			continue
		}

		for _, m := range matches {
			nr := r.Copy()
			s.addRightColumns(nr, m, schema)
			out = append(out, nr)
		}
	}

	return out, nil
}

func (s *JoinStage) resolveRightSchema(rightRecords []*record.Record) ([]string, error) {
	if s.selectPresent {
