	}
	if len(rightRecords) == 0 {
		return []string{}, nil
	}
	return rightRecords[0].Order, nil
}

func (s *JoinStage) projectRight(rr *record.Record, schema []string) (map[string]string, error) {
	vals := make(map[string]string, len(schema))
	for _, col := range schema {
		v, ok := rr.Get(col)
		if !ok {
			if s.isOn(col) {
				return nil, fmt.Errorf("join: missing on column %s in right record", col)
			}
			v = ""
		}
		vals[col] = v
	}
	return vals, nil
}

func (s *JoinStage) addRightColumns(nr *record.Record, vals map[string]string, schema []string) {
	for _, col := range schema {
		if s.isOn(col) {
			continue
		}
		v := ""
		if vals != nil {
			v = vals[col]
		}
		nr.Set(s.prefix+col, v)
	}
}

func (s *JoinStage) isOn(col string) bool {
	for _, c := range s.on {
		if c == col {
			return true
		}
	}
	return false
}

func joinKey(on []string, vals map[string]string) string {
	parts := make([]string, 0, len(on)*2)
	for _, k := range on {
		parts = append(parts, k, vals[k])
	}
	return strings.Join(parts, "\x00")
}
