        }
    }
    for _, col := range schema {
        if s.isOn(col) {
            continue
        }
        name := s.prefix + col
        if leftColumns[name] {
            return nil, fmt.Errorf("config: join: column name collision: %s", name)
        }
    }

    index := map[string][]map[string]string{}
    for _, rr := range rightRecords {
        vals, err := s.projectRight(rr, schema)
        if err != nil {
            return nil, err
        }

        skip := false
        for _, col := range s.on {
            if vals[col] == "" {
                skip = true
                break
            }
        }
        if skip {
            continue
        }

        key := joinKey(s.on, vals)
        index[key] = append(index[key], vals)
    }

    out := make([]*record.Record, 0, len(in))
    for _, r := range in {
        for _, col := range s.on {
            if !r.Has(col) {
                return nil, fmt.Errorf("join: missing on column %s in left record", col)
            }
        }

        leftVals := map[string]string{}
        empty := false
        for _, col := range s.on {
            v, _ := r.Get(col)
            leftVals[col] = v
            if v == "" {
                empty = true
            }
        }

        var matches []map[string]string
        if !empty {
            matches = index[joinKey(s.on, leftVals)]
        }

        if len(matches) == 0 {
            if s.kind == "left" {
                nr := r.Copy()
                s.addRightColumns(nr, nil, schema)
                out = append(out, nr)
            }
            continue
        }

        for _, m := range matches {
            nr := r.Copy()
            s.addRightColumns(nr, m, schema)
            out = append(out, nr)
        }
    }

    return out, nil
}

func (s *JoinStage) resolveRightSchema(rightRecords []*record.Record) ([]string, error) {
    if s.selectPresent {
        return s.selectCols, nil
    }
    if len(rightRecords) == 0 {
        return []string{}, nil
    }
    return rightRecords[0].Order, nil
}

func (s *JoinStage) projectRight(rr *record.Record, schema []string) (map[string]string, error) {
    vals := make(map[string]string, len(schema))
    for _, col := range schema {
        v, ok := rr.Get(col)
        if !ok {
            if s.isOn(col) {
                return nil, fmt.Errorf("join: missing on column %s in right record", col)
            }
            v = ""
        }
        vals[col] = v
    }
    return vals, nil
}

func (s *JoinStage) addRightColumns(nr *record.Record, vals map[string]string, schema []string) {
    for _, col := range schema {
        if s.isOn(col) {
            continue
        }
        v := ""
        if vals != nil {
            v = vals[col]
        }
        nr.Set(s.prefix+col, v)
    }
}

func (s *JoinStage) isOn(col string) bool {
    for _, c := range s.on {
        if c == col {
            return true
        }
    }
    return false
}

func schemaContains(schema []string, col string) bool {
    for _, c := range schema {
        if c == col {
            return true
        }
    }
    return false
}

func joinKey(on []string, vals map[string]string) string {
    parts := make([]string, 0, len(on)*2)
    for _, k := range on {
        parts = append(parts, k, vals[k])
    }
    return strings.Join(parts, "\x00")
}
